// @name Video player
// The videos in a folder of the frame's assets, one after another, for ever:
// by name or shuffled, each once or the one on show again and again. A tap
// shows the controls (back, pause, next, the list, the bar to seek); they go
// after a few seconds of playing. Where it was is kept on disk, so a restart
// goes on with the same file. Plays on a Raspberry Pi (docs/video.md): the
// frames are decoded by ffmpeg at the size of the box, and only the video is
// drawn again each frame.
const VIDEO = /\.(mp4|m4v|mov|mkv|webm|avi|ts|mts|m2ts|mpg|mpeg|wmv|flv|3gp|ogv)$/i
const CONTROLS_MS = 4000
const LIST_AGAIN_MS = 60000
const SKIP_FAILED_MS = 3000

// What the folder holds: read again every minute, so new files join.
let files = []
let listedFolder = null
let listedAt = 0
let order = []
// Where it is, by file (kept on disk in the private `spot` field).
let current = ''
let paused = false
let view = 'player' // or 'list'
let controlsUntil = 0
let failed = {} // file -> why, skipped until the folder is read again
let failedAt = 0
let savedAt = 0
let barWidth = 0
let restartAt = null // the file on show picked again: back to here

const baseName = (path) => path.split('/').pop()
const clock = (s) => {
  if (!(s >= 0)) return '--:--'
  const h = Math.floor(s / 3600)
  const m = Math.floor((s % 3600) / 60)
  const sec = String(Math.floor(s % 60)).padStart(2, '0')
  return h > 0 ? `${h}:${String(m).padStart(2, '0')}:${sec}` : `${m}:${sec}`
}

const readSpot = (app) => {
  let spot = app.state.spot
  if (typeof spot === 'string') {
    try {
      spot = JSON.parse(spot)
    } catch {
      spot = null
    }
  }
  return spot && typeof spot === 'object' ? spot : {}
}

const shuffled = (list) => {
  const out = list.slice()
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    const t = out[i]
    out[i] = out[j]
    out[j] = t
  }
  return out
}

const folderOf = (app) => String(app.state.folder ?? 'videos').trim().replace(/^\/+|\/+$/g, '')

function listFolder(app) {
  const folder = folderOf(app)
  const now = Date.now()
  if (listedFolder === folder && now - listedAt < LIST_AGAIN_MS) return
  // Every file below the folder, each named from the assets' top.
  const found = frameos.listAssets(folder) || []
  const before = files.join('\n')
  files = found
    .filter((name) => VIDEO.test(name) && !name.split('/').some((part) => part.startsWith('.')))
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }))
  if (listedFolder !== folder || files.join('\n') !== before) {
    order = app.state.order === 'shuffle' ? shuffled(files) : files.slice()
    failed = {}
  }
  listedFolder = folder
  listedAt = now
}

function playable() {
  return order.filter((file) => !failed[file])
}

function step(app, by) {
  const list = playable()
  if (!list.length) return
  const at = list.indexOf(current)
  let next = at < 0 ? 0 : at + by
  if (next >= list.length) {
    // Round again, in a new order when shuffled.
    if (app.state.order === 'shuffle' && list.length > 2) {
      order = shuffled(files)
      next = 0
    } else {
      next = 0
    }
  }
  if (next < 0) next = list.length - 1
  play(app, list[next], 0)
}

function play(app, file, start) {
  if (file === current) restartAt = start
  current = file
  paused = false
  frameos.setState('spot', { file, time: start })
  savedAt = Date.now()
  frameos.remember('start', start)
}

const showControls = () => {
  controlsUntil = Date.now() + CONTROLS_MS
}

const Icon = ({ d, size }) => (
  <svg className={`w-[${size}px] h-[${size}px]`} viewBox="0 0 24 24">
    <path fill="currentColor" d={d} />
  </svg>
)
const ICONS = {
  play: 'M8 5v14l11-7z',
  pause: 'M6 5h4v14H6zM14 5h4v14h-4z',
  next: 'M6 18l8.5-6L6 6v12zM16 6v12h2V6h-2z',
  back: 'M6 6h2v12H6zm3.5 6l8.5 6V6z',
  list: 'M3 13h2v-2H3v2zm0 4h2v-2H3v2zm0-8h2V7H3v2zm4 4h14v-2H7v2zm0 4h14v-2H7v2zM7 7v2h14V7H7z',
  close: 'M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z',
}

function Button({ icon, size, onClick }) {
  return (
    <div
      className={`flex items-center justify-center w-[${size * 2}px] h-[${size * 2}px] rounded-full bg-white/15 active:bg-white/40 text-white`}
      onClick={onClick}
    >
      <Icon d={ICONS[icon]} size={size} />
    </div>
  )
}

function Message({ title, text, k }) {
  return (
    <div className="w-full h-full flex flex-col items-center justify-center bg-black text-white gap-[8px]">
      <span className={`text-[${Math.round(22 * k)}px] font-bold`}>{title}</span>
      <span className={`text-[${Math.round(15 * k)}px] text-white/70 text-center px-[24px]`}>{text}</span>
    </div>
  )
}

function List({ app, k }) {
  const list = order.length ? order : files
  const row = Math.round(44 * k)
  return (
    <div className="w-full h-full flex flex-col bg-neutral-900 text-white">
      <div className={`flex items-center gap-[12px] h-[${Math.round(56 * k)}px] px-[14px] shrink-0 bg-black`}>
        <span className={`flex-1 truncate text-[${Math.round(18 * k)}px] font-bold`}>
          {`${folderOf(app) || 'Assets'} · ${files.length} video${files.length === 1 ? '' : 's'}`}
        </span>
        <Button icon="close" size={Math.round(16 * k)} onClick={() => { view = 'player'; showControls() }} />
      </div>
      <div className="flex-1 overflow-y-auto">
        {list.map((file) => (
          <div
            className={`flex items-center gap-[10px] h-[${row}px] px-[16px] border-b border-white/10 ${file === current ? 'bg-sky-700' : 'active:bg-white/20'}`}
            onClick={() => { play(app, file, 0); view = 'player'; showControls() }}
          >
            <span className={`flex-1 truncate text-[${Math.round(15 * k)}px] ${failed[file] ? 'text-white/40' : ''}`}>
              {file.slice(folderOf(app) ? folderOf(app).length + 1 : 0)}
            </span>
            {failed[file] ? <span className={`text-[${Math.round(12 * k)}px] text-red-300`}>cannot play</span> : null}
          </div>
        ))}
      </div>
    </div>
  )
}

function Controls({ app, video, k }) {
  const icon = Math.round(22 * k)
  const duration = video.duration
  const time = video.time ?? 0
  const known = duration > 0
  const seek = (e) => {
    if (!known) return
    const width = e.width ?? barWidth
    const at = Math.max(0, Math.min(1, e.localX / Math.max(width, 1))) * duration
    frameos.seekVideo(video, at)
    showControls()
  }
  const list = playable()
  return (
    <div className="absolute left-0 top-0 w-full h-full flex flex-col justify-between">
      <div className={`flex items-center gap-[10px] px-[14px] h-[${Math.round(48 * k)}px] bg-black/60 text-white`}>
        <span className={`flex-1 truncate text-[${Math.round(16 * k)}px] font-bold`}>{baseName(current)}</span>
        <span className={`text-[${Math.round(13 * k)}px] text-white/70`}>
          {`${Math.max(1, list.indexOf(current) + 1)} of ${list.length}`}
        </span>
      </div>
      <div className={`flex flex-col gap-[${Math.round(8 * k)}px] px-[16px] pb-[${Math.round(12 * k)}px] pt-[${Math.round(10 * k)}px] bg-black/60 text-white`}>
        {known ? (
          <div className={`flex items-center h-[${Math.round(24 * k)}px]`} onPointerDown={seek} onPointerMove={(e) => { if (e.buttons) seek(e) }}>
            <div className={`flex-1 h-[${Math.max(3, Math.round(5 * k))}px] rounded-full bg-white/25`}>
              <div className={`h-full rounded-full bg-sky-400 w-[${Math.round((Math.min(time, duration) / duration) * 1000) / 10}%]`} />
            </div>
          </div>
        ) : null}
        <div className="flex items-center gap-[12px]">
          <span className={`w-[${Math.round(120 * k)}px] text-[${Math.round(13 * k)}px] text-white/80`}>
            {video.live ? 'Live' : `${clock(time)} / ${clock(duration)}`}
          </span>
          <div className="flex-1 flex items-center justify-center gap-[16px]">
            <Button icon="back" size={icon} onClick={() => { step(app, -1); showControls() }} />
            <Button icon={paused ? 'play' : 'pause'} size={Math.round(icon * 1.2)} onClick={() => { paused = !paused; showControls() }} />
            <Button icon="next" size={icon} onClick={() => { step(app, 1); showControls() }} />
          </div>
          <div className={`w-[${Math.round(120 * k)}px] flex justify-end`}>
            <Button icon="list" size={icon} onClick={() => { view = 'list' }} />
          </div>
        </div>
      </div>
    </div>
  )
}

export function get(app, context) {
  const width = context?.imageWidth ?? app.frame.width
  const height = context?.imageHeight ?? app.frame.height
  const k = Math.max(0.6, Math.min(1.6, Math.min(width / 800, height / 480) * 1.15))
  barWidth = width - 32
  listFolder(app)
  if (!files.length) {
    return (
      <Message
        k={k}
        title={`No videos in “${folderOf(app) || 'the assets folder'}”`}
        text={`Copy video files (.mp4, .mkv, .webm, .mov) into the frame's assets folder, in ${folderOf(app) || 'its top'}/. The Files scene uploads them from the browser.`}
      />
    )
  }
  if (!current) {
    const spot = readSpot(app)
    if (spot.file && files.includes(spot.file)) {
      current = spot.file
      frameos.remember('start', Math.max(0, Number(spot.time) || 0))
    } else {
      play(app, playable()[0] ?? files[0], 0)
    }
  }
  if (view === 'list') return <List app={app} k={k} />

  const fit = app.state.fit === 'cover' ? 'cover' : 'contain'
  const playCurrent = () => {
    const v = frameos.video('player', {
      src: current,
      start: frameos.recall('start') ?? 0,
      loop: app.state.repeat === 'one',
      paused,
      fit,
      fps: Number(app.state.fps) || 30,
    })
    if (restartAt !== null) {
      frameos.seekVideo(v, restartAt)
      restartAt = null
    }
    return v
  }
  let video = playCurrent()
  if (video.state === 'ended') {
    // The next one now, in this render: its first frame follows the last.
    step(app, 1)
    video = playCurrent()
  } else if (video.state === 'error') {
    if (video.id === 0 && /cannot play it|, not here/.test(video.error || '')) {
      // No video on this frame at all (an ESP32, the preview): say so once.
      return <Message k={k} title="Video does not play here" text={video.error} />
    }
    if (!failed[current]) {
      failed[current] = video.error || 'cannot play'
      failedAt = Date.now()
    }
    if (playable().length === 0) {
      return <Message k={k} title="None of these videos play" text={`${baseName(current)}: ${failed[current]}`} />
    }
    if (Date.now() - failedAt >= SKIP_FAILED_MS) {
      step(app, 1)
      video = playCurrent()
    } else {
      frameos.setNextSleep(SKIP_FAILED_MS / 1000)
      return <Message k={k} title={baseName(current)} text={`Cannot play it: ${failed[current]}. Next one in a moment.`} />
    }
  } else if (video.state === 'playing' && Date.now() - savedAt > 15000) {
    // Where it is, now and then: a restart goes on from about here.
    frameos.setState('spot', { file: current, time: video.time })
    savedAt = Date.now()
  }
  const controls = paused || view !== 'player' || Date.now() < controlsUntil
  return (
    <div className="relative w-full h-full bg-black" onClick={() => { showControls() }}>
      <img className={`w-full h-full object-${fit}`} src={video} />
      {video.state === 'loading' && !controls ? (
        <span className={`absolute left-[16px] bottom-[12px] text-[${Math.round(13 * k)}px] text-white/60`}>{baseName(current)}</span>
      ) : null}
      {controls ? <Controls app={app} video={video} k={k} /> : null}
    </div>
  )
}
